scripts.build:static:
rm -rf dist && mkdir -p dist && cp index.html wechat-publisher.html wechat-dashboard.html etsy-publisher.html etsy-import.js config.js btest.html dist/ && cp -r src dist/ && node -e "const fs=require('fs');const b=process.env.WECHAT_API_BASE||'';const k=process.env.WECHAT_API_KEY||'';const c=fs.readFileSync('dist/config.js','utf8');fs.writeFileSync('dist/config.js','// 注入：后端基地址（WECHAT_API_BASE）与可选 API Key（WECHAT_API_KEY）
window.ETSYOPS_API_BASE='+JSON.stringify(b)+';
window.ETSYOPS_API_KEY='+JSON.stringify(k)+';
'+c);" && node -e "const fs=require('fs'),cp=require('child_process');let rawSha=process.env.CF_PAGES_COMMIT_SHA||'';if(!rawSha||rawSha==='null'||rawSha==='undefined'){rawSha='';}let sha=rawSha.slice(0,7);if(!sha){try{sha=cp.execSync('git rev-parse --short HEAD').toString().trim();}catch(e){sha='dev'+new Date().toISOString().slice(0,10).replace(/-/g,'');}}['index.html','wechat-publisher.html','wechat-dashboard.html','etsy-publisher.html etsy-import.js'].forEach(f=>{const p='dist/'+f;if(fs.existsSync(p)){const s=fs.readFileSync(p,'utf8');fs.writeFileSync(p,s.split('BUILD_VERSION').join(sha));}});console.log('[build] 版本号注入 ->',sha);"
